using System.IO;using System.Diagnostics;using System.Runtime.InteropServices;using System.Text;using Microsoft.Win32.SafeHandles;
namespace FaceAssets;
public sealed class GameResources {
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)]static extern uint GetFinalPathNameByHandleW(SafeFileHandle file,StringBuilder path,uint length,uint flags);
 public static string BackingPath(string path){try{using var f=File.Open(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);var b=new StringBuilder(32768);uint n=GetFinalPathNameByHandleW(f.SafeFileHandle,b,(uint)b.Capacity,0);return n>0&&n<b.Capacity?b.ToString():"unavailable";}catch(Exception e){return "unavailable: "+e.GetType().Name;}}
 public string Root{get;}public List<string> Notes{get;}=[];public bool UsvfsObserved{get;}
 public List<string> ActivePlugins{get;}=[];public bool PluginOrderVerified{get;private set;}
 readonly Dictionary<string,string> dependencyPaths=new(StringComparer.OrdinalIgnoreCase);
 public Dictionary<string,string> Fingerprints()=>dependencyPaths.Where(kv=>Path.GetExtension(kv.Key).ToLowerInvariant() is ".nif" or ".tri" or ".dds" or ".ini" or ".log").ToDictionary(kv=>kv.Key,kv=>Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(File.ReadAllBytes(kv.Value))),StringComparer.OrdinalIgnoreCase);
 readonly List<string> archives=[];readonly Dictionary<string,BsaArchive?> indexes=new(StringComparer.OrdinalIgnoreCase);readonly Dictionary<string,string> extracted=new(StringComparer.OrdinalIgnoreCase);static long cacheBytes;static readonly object cacheLock=new();long indexedNames;int indexedEntries;
 static readonly string cacheRoot=Path.Combine(Path.GetTempPath(),"FacialStudio-Resources-"+Guid.NewGuid().ToString("N"));
 static GameResources(){AppDomain.CurrentDomain.ProcessExit+=(_,_)=>{try{if(Directory.Exists(cacheRoot))Directory.Delete(cacheRoot,true);}catch{}};}
 public static string? CachedLogicalPath(string path){string absolute=Path.GetFullPath(path);if(!absolute.StartsWith(cacheRoot+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return null;string relative=Path.GetRelativePath(cacheRoot,absolute);int slash=relative.IndexOf(Path.DirectorySeparatorChar);return slash<0?null:relative[(slash+1)..].Replace('\\','/');}
 public GameResources(string root){Root=Path.GetFullPath(root);if(!Directory.Exists(Root))throw new DirectoryNotFoundException(Root);try{UsvfsObserved=Process.GetCurrentProcess().Modules.Cast<ProcessModule>().Any(m=>m.ModuleName.StartsWith("usvfs",StringComparison.OrdinalIgnoreCase));}catch{}Notes.Add("Resource root: "+Root+" / USVFS module observed: "+UsvfsObserved+" (not proof of active profile)");}
 public string PathFor(string rel){rel=rel.Replace('\\',Path.DirectorySeparatorChar).Replace('/',Path.DirectorySeparatorChar);if(Path.IsPathRooted(rel)||rel.Split(Path.DirectorySeparatorChar).Any(x=>x==".."||x.Contains(':')))throw new InvalidDataException("Unsafe resource path: "+rel);string path=Path.GetFullPath(Path.Combine(Root,rel));if(!path.StartsWith(Root.TrimEnd(Path.DirectorySeparatorChar)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Resource escapes root");return path;}
 public string? Find(string rel){var p=PathFor(rel);if(File.Exists(p)){dependencyPaths[rel.Replace('\\','/')]=p;return p;}rel=BsaArchive.Normalize(rel);foreach(string archive in archives.AsEnumerable().Reverse()){
  var index=Index(archive);
  if(index==null||!index.Entries.TryGetValue(rel,out var entry))continue;
  string key=archive+"|"+rel;if(extracted.TryGetValue(key,out string? existing)&&File.Exists(existing)){dependencyPaths[rel]=existing;return existing;}
  try{byte[] bytes=index.Read(entry);string id=Convert.ToHexString(System.Security.Cryptography.SHA256.HashData(Encoding.UTF8.GetBytes(archive+"|"+new FileInfo(archive).Length+"|"+new FileInfo(archive).LastWriteTimeUtc.Ticks)))[..24];string target=Path.Combine(cacheRoot,id,rel.Replace('/',Path.DirectorySeparatorChar));lock(cacheLock){bool exists=File.Exists(target);if(!exists&&cacheBytes+bytes.Length>512L*1024*1024)throw new InvalidDataException("Session resource cache exceeds 512 MiB");Directory.CreateDirectory(Path.GetDirectoryName(target)!);File.WriteAllBytes(target,bytes);if(!exists)cacheBytes+=bytes.Length;}extracted[key]=target;dependencyPaths[rel]=target;Notes.Add("BSA resource: "+Path.GetFileName(archive)+" -> "+rel);return target;}catch(Exception e){Notes.Add("BSA resource rejected (no older replacement): "+archive+" / "+rel+": "+e.Message);return null;}
 }return null;}
 BsaArchive? Index(string archive){
  if(!indexes.TryGetValue(archive,out var index)){try{index=new BsaArchive(archive);indexedNames+=index.Entries.Keys.Sum(k=>(long)k.Length);indexedEntries+=index.Entries.Count;if(indexedEntries>1000000||indexedNames>64L*1024*1024)throw new InvalidDataException("Combined BSA index budget exceeded");}catch(Exception e){Notes.Add("BSA index rejected: "+Path.GetFileName(archive)+": "+e.Message);index=null;}indexes[archive]=index;}
  return index;
 }
 public IEnumerable<string> EnumerateResources(string folder,string extension,bool recursive){
  string directory=PathFor(folder);string prefix=BsaArchive.Normalize(folder).TrimEnd('/')+"/";var names=new HashSet<string>(StringComparer.OrdinalIgnoreCase);
  if(Directory.Exists(directory))foreach(string file in Directory.EnumerateFiles(directory,"*"+extension,recursive?SearchOption.AllDirectories:SearchOption.TopDirectoryOnly)){names.Add(Path.GetRelativePath(Root,file).Replace('\\','/'));if(names.Count>10000)throw new InvalidDataException("Resource enumeration budget");}
  foreach(string archive in archives){var index=Index(archive);if(index==null)continue;foreach(string name in index.Entries.Keys)if(name.StartsWith(prefix,StringComparison.OrdinalIgnoreCase)&&name.EndsWith(extension,StringComparison.OrdinalIgnoreCase)&&(recursive||!name[prefix.Length..].Contains('/'))){names.Add(name);if(names.Count>10000)throw new InvalidDataException("Resource enumeration budget");}}
  return names.OrderBy(n=>n,StringComparer.OrdinalIgnoreCase).ToList();
 }
 public void Configure(IEnumerable<string> referencedPlugins){
  archives.Clear();ActivePlugins.Clear();string list=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"Skyrim Special Edition","plugins.txt");
  if(UsvfsObserved&&File.Exists(list)&&new FileInfo(list).Length<1024*1024){ActivePlugins.AddRange(File.ReadLines(list).Where(l=>l.StartsWith('*')).Select(l=>l[1..].Trim()).Where(ValidPlugin).Distinct(StringComparer.OrdinalIgnoreCase));string backing=BackingPath(list);PluginOrderVerified=backing.Replace('\\','/').Contains("/profiles/",StringComparison.OrdinalIgnoreCase);Notes.Add("Observed plugin list: "+list+" -> "+backing+"; MO2 profile backing verified: "+PluginOrderVerified);}
  if(ActivePlugins.Count==0)Notes.Add("Active MO2 plugin order unavailable; referenced plugins/masters only. Archive/record override order is not proven.");
  void Archive(string name){if(Path.GetFileName(name)!=name||!name.EndsWith(".bsa",StringComparison.OrdinalIgnoreCase))return;string path=PathFor(name);if(File.Exists(path)){archives.RemoveAll(p=>p.Equals(path,StringComparison.OrdinalIgnoreCase));archives.Add(path);}}
  string game=Path.GetDirectoryName(Root)!;var inis=new[]{Path.Combine(game,"Skyrim.ini"),Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments),"My Games","Skyrim Special Edition","Skyrim.ini")};
  foreach(string ini in inis)if(File.Exists(ini)&&new FileInfo(ini).Length<1024*1024){string section="";foreach(string line in File.ReadLines(ini)){string text=line.Trim();if(text.StartsWith('['))section=text.Trim('[',']');int at=text.IndexOf('=');if(section.Equals("Archive",StringComparison.OrdinalIgnoreCase)&&at>0&&text[..at].StartsWith("sResourceArchiveList",StringComparison.OrdinalIgnoreCase))foreach(string name in text[(at+1)..].Split(','))Archive(name.Trim());}}
  // Explicit base-game defaults, used only when visible in this Data tree.
  if(archives.Count==0)foreach(string name in new[]{"Skyrim - Meshes0.bsa","Skyrim - Meshes1.bsa","Skyrim - Textures0.bsa","Skyrim - Textures1.bsa","Skyrim - Textures2.bsa","Skyrim - Textures3.bsa","Skyrim - Textures4.bsa","Skyrim - Textures5.bsa","Skyrim - Textures6.bsa","Skyrim - Textures7.bsa","Skyrim - Textures8.bsa"})Archive(name);
  foreach(string plugin in (ActivePlugins.Count>0?ActivePlugins:referencedPlugins).Where(ValidPlugin).Distinct(StringComparer.OrdinalIgnoreCase)){string stem=Path.GetFileNameWithoutExtension(plugin);Archive(stem+".bsa");Archive(stem+" - Main.bsa");Archive(stem+" - Textures.bsa");}
  if(archives.Count>2048)throw new InvalidDataException("Archive count budget");
 }
 static bool ValidPlugin(string name)=>Path.GetFileName(name)==name&&Path.GetExtension(name).ToLowerInvariant() is ".esm" or ".esp" or ".esl";
 public string? Mesh(string rel)=>Find(rel.Replace('\\','/').StartsWith("meshes/",StringComparison.OrdinalIgnoreCase)?rel:"meshes/"+rel);
 public string? Texture(string rel)=>Find(rel.Replace('\\','/').StartsWith("textures/",StringComparison.OrdinalIgnoreCase)?rel:"textures/"+rel);
 public static string? Detect(){foreach(var start in new[]{Environment.CurrentDirectory,AppContext.BaseDirectory}){for(var d=new DirectoryInfo(start);d!=null;d=d.Parent){if(File.Exists(Path.Combine(d.FullName,"Skyrim.esm")))return d.FullName;if(File.Exists(Path.Combine(d.FullName,"Data","Skyrim.esm")))return Path.Combine(d.FullName,"Data");string ini=Path.Combine(d.FullName,"ModOrganizer.ini");if(File.Exists(ini)&&new FileInfo(ini).Length<1024*1024){foreach(var l in File.ReadLines(ini))if(l.StartsWith("gamePath=",StringComparison.OrdinalIgnoreCase)){string path=l[9..].Trim();if(path.StartsWith("@ByteArray(")&&path.EndsWith(')'))path=path[11..^1];path=path.Replace("\\\\","\\");if(Directory.Exists(Path.Combine(path,"Data")))return Path.Combine(path,"Data");}}}}return null;}
 public void Missing(string rel){Notes.Add("Resource unavailable: "+rel+". Not visible as loose data or in the configured BSA order; check the current profile/plugin resource or connect it manually.");}
}
